BEGIN;

-- Bind each one-time authorization code to the exact state generated by
-- D Hosting. Existing codes are invalidated by assigning an unmatchable hash.
ALTER TABLE hosting_authorization_codes
  ADD COLUMN IF NOT EXISTS state_hash CHAR(64) NOT NULL
  DEFAULT repeat('0', 64);

ALTER TABLE hosting_authorization_codes
  ALTER COLUMN state_hash DROP DEFAULT;

COMMIT;
